import { tv, type VariantProps } from "@/lib/beton/tv";

export const marquee = tv({
  slots: {
    root: "group flex w-full overflow-hidden",
    track: [
      "flex w-max shrink-0 items-center",
      "motion-safe:animate-marquee motion-reduce:animate-none",
      "group-hover:[animation-play-state:paused]",
    ],
    item: "shrink-0",
  },
  variants: {
    direction: {
      left: {},
      right: { track: "motion-safe:animate-marquee-reverse" },
    },
    gap: {
      sm: { track: "gap-4 pr-4", item: "" },
      md: { track: "gap-8 pr-8", item: "" },
      lg: { track: "gap-12 pr-12", item: "" },
    },
    bordered: {
      true: { root: "border-y-3 border-border bg-raised py-3" },
    },
  },
  defaultVariants: {
    direction: "left",
    gap: "md",
    bordered: false,
  },
});

export type MarqueeVariants = VariantProps<typeof marquee>;

"use client";

import { marquee, type MarqueeVariants } from "@/lib/beton/recipes/marquee.recipe";
import type { ComponentProps, CSSProperties, ReactNode } from "react";

export interface MarqueeProps extends ComponentProps<"div">, MarqueeVariants {
  /** How long one full pass takes, in seconds. */
  duration?: number;
  /** How many copies to draw. Two is enough unless the content is very short. */
  copies?: number;
  children?: ReactNode;
}

/**
 * Content that slides past, forever. It pauses on hover, and holds still for
 * anyone who has asked for less motion.
 */
export function Marquee({
  direction = "left",
  gap = "md",
  bordered = false,
  duration = 20,
  copies = 2,
  className,
  style,
  children,
  ...props
}: MarqueeProps) {
  const styles = marquee({ direction, gap, bordered });
  const passes = Math.max(2, Math.trunc(copies));
  return (
    <div
      {...props}
      data-direction={direction}
      className={styles.root({ class: className })}
      style={{ ...style, "--marquee-duration": `${duration}s` } as CSSProperties}
    >
      {Array.from({ length: passes }, (_, index) => (
        // Only the first pass is read out; the rest are the same words again.
        <div key={index} aria-hidden={index > 0} className={styles.track()}>
          {children}
        </div>
      ))}
    </div>
  );
}
